// The renderer-to-Electron-main edge declaration: window and OS
// capabilities only. Agent data never rides this edge; those methods belong
// to the coordinator edge, and the remaining preload agent-data bridge is
// migration debt the renderer waves delete. Desktop method families migrate
// into this declaration as their payload types finish rehoming into shared.

import {
	declareRpcContract,
	type EdgeBridge,
	type EdgeMethodTable,
	type RpcMethod,
} from "@sand/dune/rpc";

