export interface DownloadAttachmentArgs {
	readonly path: string;
	readonly suggestedName?: string;
}

export type AcceptedRecreateComputerResult =
	| {
			readonly status: "started";
			readonly operationId: SandBoxMigrationOperationId;
	  }
	| { readonly status: "started-untrackable" };

export type RecreateComputerResult =
	| AcceptedRecreateComputerResult
	| { readonly status: "dev-fallback" };

export type UpdateComputerResult =
	| AcceptedRecreateComputerResult
	| { readonly status: "dev-fallback-finished" };

export interface RecreateComputerArgs {
	readonly preserveData: boolean;
	readonly force?: boolean;
}

export type ForceRecreateComputerResult =
	| AcceptedRecreateComputerResult
	| { readonly status: "rejected"; readonly reason: string };

/**
 * The desktop families the DesktopSource port consumes today: theme, update
 * status and commands, window state and controls, deep-link delivery,
 * desktop preferences (onboarding, time zone, sidebar), openExternal, the
 * native dialog pickers, the encrypted secrets CRUD (OS keychain), and the
 * MCP manager family (main's desktop-local SandMcpManager). The
 * platform/isDev constants stay on the legacy preload bridge and join as a
 * later family.
 *
 * The sidebar-collapsed preference is declared ahead of its wire: no main
 * handler exists yet, so the desktop advertises `sidebarPreferenceV1` only
 * once the family lands. `window-state` carries the wire's own
 * `SandWindowState`; window focus joins the payload when a consumer exists.
 */
export interface MainRpcContract {
	readonly methods: {
		readonly openExternal: RpcMethod<{ readonly url: string }, void>;
		readonly submitFeedback: RpcMethod<SandFeedbackSubmitArgs, SandFeedbackSubmitResult>;
		readonly getDesktopEnvironment: RpcMethod<Record<string, never>, SandDesktopEnvironment>;
		readonly getWindowState: RpcMethod<Record<string, never>, SandWindowState>;
		readonly minimizeWindow: RpcMethod<Record<string, never>, void>;
		readonly toggleMaximizeWindow: RpcMethod<Record<string, never>, void>;
		readonly closeWindow: RpcMethod<Record<string, never>, void>;
		readonly resizeWindowWidth: RpcMethod<{ readonly deltaWidth: number }, number>;
		readonly setTitleBarOverlayTone: RpcMethod<{ readonly isOverlayTone: boolean }, void>;
		readonly getThemeState: RpcMethod<Record<string, never>, SandThemeState>;
		readonly setThemePreference: RpcMethod<
			{ readonly preference: SandThemePreference },
			SandThemeState
		>;
		readonly getEgressTunnelEnabled: RpcMethod<Record<string, never>, boolean>;
		readonly setEgressTunnelEnabled: RpcMethod<{ readonly enabled: boolean }, boolean>;
		readonly getEgressTunnelStatus: RpcMethod<Record<string, never>, SandEgressTunnelStatus>;
		readonly getWebauthnProxyEnabled: RpcMethod<Record<string, never>, boolean>;
		readonly setWebauthnProxyEnabled: RpcMethod<{ readonly enabled: boolean }, boolean>;
		readonly getUpdateStatus: RpcMethod<Record<string, never>, SandUpdateStatus>;
		readonly checkForUpdates: RpcMethod<Record<string, never>, SandUpdateStatus>;
		readonly setUpdateTrack: RpcMethod<
			{ readonly track: SandUpdateTrack | null },
			SandUpdateStatus
		>;
		readonly quitAndInstallUpdate: RpcMethod<Record<string, never>, void>;
		readonly setAutoUpdateWhenIdleOptIn: RpcMethod<{ readonly enabled: boolean }, SandUpdateStatus>;
		readonly getBoxMigrationStatus: RpcMethod<
			Record<string, never>,
			SandBoxMigrationClientEvent | null
		>;
		readonly getOnboardingSeen: RpcMethod<Record<string, never>, boolean>;
		readonly setOnboardingSeen: RpcMethod<{ readonly seen: boolean }, void>;
		readonly getTimeZone: RpcMethod<Record<string, never>, SandTimeZoneSetting>;
		readonly setTimeZoneOverride: RpcMethod<
			{ readonly timeZone: string | null },
			SandTimeZoneSetting
		>;
		readonly getAutoReviewInstructions: RpcMethod<
			Record<string, never>,
			SandAutoReviewInstructions
		>;
		readonly setAutoReviewInstructions: RpcMethod<
			{ readonly instructions: SandAutoReviewInstructions },
			SandAutoReviewInstructions
		>;
		// The three-state permission for tools that act on the user's own computer.
		// The desktop owns the durable value; the Host mirrors and enforces it.
		readonly getLocalToolPermission: RpcMethod<Record<string, never>, SandLocalToolPermission>;
		// The team admin's ceiling on the above, or null when the team states no
		// policy. Read by Settings so it can say an admin is holding the value
		// rather than silently showing something the member did not pick.
		readonly getLocalToolPermissionCeiling: RpcMethod<
			Record<string, never>,
			SandLocalToolPermission | null
		>;
		readonly setLocalToolPermission: RpcMethod<
			{ readonly permission: SandLocalToolPermission },
			SandLocalToolPermission
		>;
		// Records on THIS machine that the user approved ONE local action, by its
		// opaque id. The in-box Host owns the ask flow, but the machine keeps its
		// own record so a box that mis-states the setting still cannot get local
		// work to run without a real human answer to that exact action.
		readonly recordLocalToolApproval: RpcMethod<
			{
				readonly approvalId: string;
				// What the card showed. The machine checks incoming work against
				// these, so one answer cannot be attached to different work.
				readonly action: SandLocalToolAction;
				readonly target: string;
			},
			void
		>;
		// Drops every approval this machine still honors — the user sent a new
		// message, so nothing they approved earlier still applies.
		readonly clearLocalToolApprovals: RpcMethod<Record<string, never>, void>;
		readonly getSidebarCollapsed: RpcMethod<Record<string, never>, boolean>;
		readonly setSidebarCollapsed: RpcMethod<{ readonly isCollapsed: boolean }, void>;
		readonly pickAvatarSource: RpcMethod<Record<string, never>, string | null>;
		readonly pickAvatarFile: RpcMethod<Record<string, never>, SandPickedAvatarFile | null>;
		readonly generateAgentAvatarImage: RpcMethod<{ readonly description: string }, string>;
		readonly resolveAttachmentMedia: RpcMethod<
			{ readonly source: string },
			ResolvedAttachmentMedia | null
		>;
		readonly readAttachmentText: RpcMethod<
			{ readonly path: string },
			ResolvedTextAttachment | null
		>;
		readonly readAttachmentBytes: RpcMethod<
			{ readonly path: string; readonly maxBytes?: number },
			ResolvedAttachmentBytes | null
		>;
		readonly stageAttachmentBytes: RpcMethod<
			{ readonly filename: string; readonly bytes: Uint8Array },
			StageAttachmentResult
		>;
		readonly downloadAttachment: RpcMethod<DownloadAttachmentArgs, boolean>;
		// Staged-attachment transfer: a send's staged local copies move to
		// the Host and resolve as Host-readable paths aligned by index (a
		// null reply is the legacy transfer-failed verdict). Desktop file
		// staging, not agent data: the copies live on this machine until
		// the Host accepts them, so the family rides the main edge and the
		// send journal consumes it as its attachment port.
		readonly commitStagedAttachments: RpcMethod<
			{ readonly paths: readonly string[]; readonly filenames: readonly string[] },
			readonly string[] | null
		>;
		readonly discardStagedAttachment: RpcMethod<{ readonly path: string }, void>;
		readonly forceRecreateComputer: RpcMethod<Record<string, never>, ForceRecreateComputerResult>;
		// The data-preserving shared-computer update. Desktop, not agent
		// data: main drives the backend-orchestrated recreate through its
		// control-plane connector (the gateway is only its dev fallback), so
		// the family rides this edge exactly like forceRecreateComputer.
		// `id` names the agent whose monitor comes back up after the swap.
		readonly updateComputer: RpcMethod<
			{ readonly id: string; readonly force?: boolean },
			UpdateComputerResult
		>;
		readonly forceReconnectGateway: RpcMethod<Record<string, never>, void>;
		// The desktop's Statsig snapshot (renderer-consumed slice; see
		// shared/experiments.ts). Null when the desktop's experiment service
		// has not started, so a gate read fails closed instead of guessing.
		readonly getExperimentsSnapshot: RpcMethod<
			Record<string, never>,
			SandExperimentsSnapshot | null
		>;
		// Internal-only feature-flag override write (the palette's Feature Flags
		// menu). The desktop's experiment service treats every command as a no-op
		// unless the user is on the Anysphere team or running a dev build, so a
		// renderer that never shows the menu also never issues one.
		readonly applyFeatureFlagOverride: RpcMethod<
			{ readonly command: SandFeatureFlagOverrideCommand },
			void
		>;
		// Internal-only manual live Statsig re-fetch (the palette's "Refresh Flags"
		// action). Forces an immediate bootstrap + re-broadcast so the panel and
		// gates reflect the user's current live values without waiting out the
		// 5-min background poll. The menu never registers for a user without it,
		// so their renderer never issues this.
		readonly refreshFeatureFlags: RpcMethod<Record<string, never>, void>;
		readonly startRpcTraceWindow: RpcMethod<Record<string, never>, boolean>;
		// The host-owned default model the main Sand agent runs on. Null means
		// unset; the baked-in default fills the gap.
		readonly getAgentDefaultModel: RpcMethod<Record<string, never>, SandAgentDefaultModel | null>;
		readonly setAgentDefaultModel: RpcMethod<
			{ readonly model: SandAgentDefaultModel },
			SandAgentDefaultModel | null
		>;
		// The box-owned pinned-agent list (ordered ids). Main reads it fresh from
		// the box and writes through the serialized host-settings push. `null` is never-written
		// (absent on the wire); a `[]` is an intentional clear; a rejection is a
		// transport failure the renderer must NOT read as empty. The setter replies
		// with the box's PERSISTED list so the caller adopts the authoritative echo
		// (null when an older host dropped the field).
		readonly getHostPinnedAgents: RpcMethod<Record<string, never>, readonly string[] | null>;
		readonly setHostPinnedAgents: RpcMethod<
			{ readonly pinnedAgentIds: readonly string[] },
			readonly string[] | null
		>;
		readonly getHostSidebarSections: RpcMethod<
			Record<string, never>,
			readonly SidebarSectionRecord[] | null
		>;
		readonly setHostSidebarSections: RpcMethod<
			{ readonly sections: readonly SidebarSectionRecord[] },
			readonly SidebarSectionRecord[] | null
		>;
		// The user-available model catalog, fetched by main with the
		// desktop's backend auth. Proto JSON as the wire carries it: the
		// contract stays proto-free, and the picker parses the payload at
		// its own boundary with the shared @anysphere/ui machinery.
		readonly getAvailableModels: RpcMethod<Record<string, never>, unknown>;
		readonly transcribeAudio: RpcMethod<
			{
				readonly audio: Uint8Array;
				readonly mimeType: string;
				readonly language?: string;
			},
			{ readonly text: string; readonly transcriptionTimeMs: number }
		>;
		readonly getCursorAuthStatus: RpcMethod<Record<string, never>, SandCursorAuthStatus>;
		readonly loginCursor: RpcMethod<Record<string, never>, SandCursorAuthStatus>;
		readonly cancelCursorLogin: RpcMethod<Record<string, never>, SandCursorAuthStatus>;
		readonly logoutCursor: RpcMethod<Record<string, never>, SandCursorAuthStatus>;
		readonly updateCursorAccountName: RpcMethod<{ readonly name: string }, SandCursorAuthStatus>;
		readonly getCursorAvatar: RpcMethod<Record<string, never>, string | null>;
		// Null when there is no Sand weekly allowance to report (signed out, no
		// standalone Sand included limit, or a failed read). Never a zeroed
		// stand-in.
		readonly getCursorWeeklyUsage: RpcMethod<Record<string, never>, SandWeeklyUsage | null>;
		// Null means signed out; a failed read rejects.
		readonly getCursorUsageSummary: RpcMethod<Record<string, never>, SandUsageSummary | null>;
		readonly getCursorPrivacyModeEnabled: RpcMethod<Record<string, never>, boolean>;
		readonly getSandAccess: RpcMethod<Record<string, never>, SandAccess>;
		readonly invokeCursorDashboardAction: RpcMethod<
			{ readonly action: string; readonly args: Record<string, string> },
			SandDashboardActionResult
		>;
		readonly reportAgentLoad: RpcMethod<SandAgentLoadReport, void>;
		readonly reportAgentsUnreachable: RpcMethod<SandAgentsUnreachableReport, void>;
		readonly reportRecoveryAction: RpcMethod<SandRecoveryActionReport, void>;
		readonly reportRebuildLifecycle: RpcMethod<SandRebuildLifecycleReport, void>;
		readonly reportReconciliation: RpcMethod<SandReconciliationReport, void>;
		readonly reportBoxVisibility: RpcMethod<SandBoxVisibilityReport, void>;
		readonly reportSendLatency: RpcMethod<SandSendLatencyReport, void>;
		readonly reportSendAck: RpcMethod<SandSendAckReport, void>;
		readonly reportReactionAck: RpcMethod<SandReactionAckReport, void>;
		readonly reportRenderTtfr: RpcMethod<SandRenderTtfrReport, void>;
		readonly reportRenderStream: RpcMethod<SandRenderStreamReport, void>;
		readonly reportVncSession: RpcMethod<SandVncSessionReport, void>;
		readonly reportVncLiveness: RpcMethod<SandVncLivenessReport, void>;
		readonly reportOpenComputer: RpcMethod<SandOpenComputerReport, void>;
		readonly reportUpdatePrompt: RpcMethod<SandUpdatePromptReport, void>;
		readonly reportSigninGate: RpcMethod<SandSigninGateReport, void>;
		readonly reportOnboardingStep: RpcMethod<SandOnboardingStepReport, void>;
		readonly reportClientFailure: RpcMethod<SandClientFailureReport, void>;
		// Opens a cloud agent in the Cursor web app in the system browser —
		// desktop, not agent data: main builds the env-aware URL, like openExternal.
		readonly openCloudAgent: RpcMethod<{ readonly bcId: string }, void>;
		// Link metadata for URLs the agent drops into prose. A desktop
		// family: main resolves it through the active agent's fetch cache
		// and its own network stack; null is the settled "no preview"
		// verdict for an unreachable or headless URL.
		readonly getLinkMetadata: RpcMethod<{ readonly url: string }, SandLinkMetadata | null>;
		// Box secrets: the desktop's encrypted store behind main's
		// trusted-sender gate. Desktop-native, not agent data: values live
		// in the OS keychain on THIS machine, and only the box-side status
		// read (getBoxSecretsStatus) is gateway data. Key NAMES cross the
		// wire freely; a VALUE crosses only on the dedicated reveal call (an
		// explicit user action) and on upsert (the paste itself).
		readonly listSecrets: RpcMethod<Record<string, never>, SecretsList>;
		readonly revealSecret: RpcMethod<{ readonly key: string }, string | null>;
		readonly upsertSecrets: RpcMethod<
			{ readonly entries: Readonly<Record<string, string>> },
			SecretsSyncResult
		>;
		readonly removeSecrets: RpcMethod<{ readonly keys: readonly string[] }, SecretsSyncResult>;
		// The MCP manager family. Desktop-native: main's desktop-local
		// SandMcpManager owns the marketplace catalog, account-config
		// writes, and backend-brokered OAuth, and the popularity and logo
		// reads use main's own backend auth. The agent's Host runs a
		// SEPARATE manager in the box; main nudges it over the gateway
		// after mutations, and the box's stdio server statuses arrive as
		// the gateway edge's mcp-servers-updated events.
		readonly getMcpState: RpcMethod<Record<string, never>, SandMcpState>;
		// The user's effective plugins (GetEffectiveUserPlugins): the
		// server-side install records the marketplace Installed state derives
		// from, keyed by stable plugin id.
		readonly getEffectivePlugins: RpcMethod<Record<string, never>, readonly SandEffectivePlugin[]>;
		readonly getMcpCatalog: RpcMethod<Record<string, never>, readonly SandMcpCatalogEntryView[]>;
		readonly getMcpTeamPopularity: RpcMethod<
			Record<string, never>,
			Readonly<Record<string, number>>
		>;
		readonly getMcpPluginLogo: RpcMethod<{ readonly url: string }, string | null>;
		readonly installEntry: RpcMethod<SandInstallEntryRequest, SandMcpState>;
		// Replaces an installed marketplace plugin's stored variable values
		// (backend UpdateUserPluginInstall); the reply is the refreshed listing
		// after the backend re-expands the synced MCP rows.
		readonly updatePluginInstall: RpcMethod<SandUpdatePluginInstallRequest, SandMcpState>;
		readonly removeMcpServer: RpcMethod<{ readonly serverId: string }, SandMcpRemoveResult>;
		// Uninstalls a marketplace plugin by its STABLE plugin id
		// (UninstallUserPlugin; the backend does all deletion). The reply's
		// `removed` is verified by read-back — effective plugins + the
		// refreshed listing — never assumed.
		readonly uninstallPlugin: RpcMethod<{ readonly pluginId: string }, SandMcpRemoveResult>;
		// `accountKey` is optional only for legacy account-unaware callers, which
		// land on "default".
		readonly authenticateMcpServer: RpcMethod<
			{ readonly serverId: string; readonly accountKey?: string },
			SandMcpAuthResult
		>;
		// Per-account lifecycle on a connector row (backend-brokered; the
		// desktop manager relays to RenameMcpOAuthAccount /
		// DeleteMcpOAuthAccount). Both reply with the refreshed listing.
		readonly renameMcpAccount: RpcMethod<
			{
				readonly serverId: string;
				readonly accountKey: string;
				readonly newAccountKey: string;
			},
			SandMcpState
		>;
		readonly removeMcpAccount: RpcMethod<
			{ readonly serverId: string; readonly accountKey: string },
			SandMcpState
		>;
		readonly setMcpCustomInstructions: RpcMethod<SandSetMcpInstructionsRequest, SandMcpState>;
		// The settings Tools section: the server row's tools with per-tool
		// disabled state, read lazily on detail open (tool definitions stay
		// with the manager; the listing summary carries only counts). The
		// toggle replies with the refreshed tool list (its read-back).
		readonly listMcpServerTools: RpcMethod<
			{ readonly serverId: string },
			readonly SandMcpServerTool[]
		>;
		readonly toggleMcpToolDisabled: RpcMethod<
			SandToggleMcpToolDisabledRequest,
			readonly SandMcpServerTool[]
		>;
	};
	readonly events: {
		readonly "theme-changed": SandThemeState;
		readonly "egress-tunnel-changed": boolean;
		readonly "egress-tunnel-status-changed": SandEgressTunnelStatus;
		readonly "webauthn-proxy-changed": boolean;
		readonly "update-status": SandUpdateStatus;
		readonly "window-state": SandWindowState;
		// The webContents page-zoom factor changed (Cmd+/-/0). A native
		// window fact: the frameless window-chrome CSS counter-zooms against
		// it so caption controls keep a constant physical size. Seeded
		// synchronously through DesktopSource.initialZoomFactor for the
		// first paint; this event carries every later change.
		readonly "zoom-factor-changed": { readonly factor: number };
		readonly "deep-link": SandDeepLink;
		readonly "open-feedback": Record<string, never>;
		readonly "open-about": Record<string, never>;
		readonly "box-migration": SandBoxMigrationClientEvent;
		// The user clicked an OS notification for this agent: a native intent
		// to focus that conversation. Desktop-originated (main raises the
		// notification and observes the click), so it rides this edge, not the
		// agent-data one; the Client's selection command is its consumer.
		readonly "focus-agent": { readonly id: string };
		// The user's real pointer is over the interactive box desktop.
		// Reported by the noVNC webview preload on THIS machine (the only
		// place the user's mouse events land), so it is a native-desktop
		// fact and never touches the gateway.
		readonly "vnc-user-presence": { readonly isPresent: boolean };
		// Dev-only: the standalone dev-controls panel recreated the local box
		// container directly (no backend migration phase exists for it), so
		// this desktop broadcast is the rebuild cover's only cue on that
		// path. Never emitted in packaged builds.
		readonly "dev-box-rebuild": { readonly type: "start" };
		// Dev-only: the live image-pull percent of a desktop-run dev-box
		// recreate (SandDevBoxPullProgressEvent documents why only the
		// desktop can observe it). Never emitted in packaged builds.
		readonly "dev-box-pull-progress": SandDevBoxPullProgressEvent;
		// The desktop re-resolved its Statsig snapshot (startup completion,
		// auth change, live config update). Carries the fresh snapshot so
		// gate reads never need a follow-up fetch.
		readonly "experiments-changed": SandExperimentsSnapshot;
		readonly "cursor-auth-changed": SandCursorAuthStatus;
		readonly "force-onboarding": Record<string, never>;
		readonly "skip-onboarding": Record<string, never>;
		readonly "widget-gallery": SandWidgetGalleryEvent;
		// The desktop MCP manager's completion watch saw a settings-started
		// OAuth's credential land in the backend. Desktop-originated (main's
		// own manager observes the completion and reloads the Host's
		// separate manager), so it rides this edge; the box-pushed
		// mcp-servers-updated family stays on the gateway edge.
		readonly "mcp-auth-completed": SandMcpAuthCompletion;
	};
	readonly capabilities: "sidebarPreferenceV1";
	readonly failureCodes: never;
}

