// Electron context isolation keeps the MessagePort here and gives the page a proxied handle.

export interface CoordinatorPortHandle {
	postMessage(message: unknown): void;
	close(): void;
	addEventListener(type: "message" | "close", listener: (event: { data?: unknown }) => void): void;
	start?(): void;
}

export interface CoordinatorPortConsumer {
	onPort(port: CoordinatorPortHandle): void;
}

export interface CoordinatorPortClaim {
	request(): void;
	release(): void;
}

export interface CoordinatorPortBridge {
	claim(consumer: CoordinatorPortConsumer): CoordinatorPortClaim | null;
}

export interface CoordinatorPortBroker {
	readonly bridge: CoordinatorPortBridge;
	deliver(port: CoordinatorPortHandle): void;
}

export interface CreateCoordinatorPortBrokerOptions {
	readonly invokeRequest: () => void;
}

export function createCoordinatorPortBroker(
	options: CreateCoordinatorPortBrokerOptions,
): CoordinatorPortBroker {
	let owner: CoordinatorPortConsumer | null = null;

	return {
		bridge: {
			claim(consumer) {
				if (owner != null) return null;
				owner = consumer;
				return {
					request: () => {
						if (owner !== consumer) return;
						options.invokeRequest();
					},
					release: () => {
						if (owner !== consumer) return;
						owner = null;
					},
				};
			},
		},
		deliver(port) {
			owner?.onPort(port);
		},
	};
}

// Electron contextBridge proxies functions but cannot transfer the real MessagePort.
export function wrapTransferredCoordinatorPort(port: MessagePort): CoordinatorPortHandle {
	return {
		postMessage: (message) => {
			port.postMessage(message);
		},
		close: () => {
			port.close();
		},
		start: () => {
			port.start();
		},
		addEventListener: (type, listener) => {
			if (type === "message") {
				port.addEventListener("message", (event) => {
					listener({ data: event.data });
				});
				return;
			}
			port.addEventListener("close", () => {
				listener({});
			});
		},
	};
}
