import type {
	EdgeMethodTable,
	RpcContractShape,
	RpcContractTag,
	RpcEventHandlers,
	RpcEventsDeclared,
} from "./contract.js";

export type EdgeTrustPolicy<S> =
	| {
			readonly kind: "require";
			readonly test: (sender: S) => boolean;
			readonly denial: string;
	  }
	| { readonly kind: "open"; readonly why: string };

export type EdgeTrustPolicies<S> = Readonly<Record<string, EdgeTrustPolicy<S>>>;

export type EdgeHandlerArgs<
	C extends RpcContractShape,
	M extends keyof C["methods"],
	P,
> = P extends { readonly kind: "open" } ? unknown : C["methods"][M]["args"];

export type EdgeHandlerRun<C extends RpcContractShape, M extends keyof C["methods"], S, P> = (
	args: EdgeHandlerArgs<C, M, P>,
	sender: S,
) => Promise<C["methods"][M]["reply"]> | C["methods"][M]["reply"];

export type EdgeHandler<
	C extends RpcContractShape,
	M extends keyof C["methods"],
	S,
	T extends EdgeTrustPolicies<S>,
> = {
	[N in keyof T & string]: {
		readonly trust: N;
		readonly run: EdgeHandlerRun<C, M, S, T[N]>;
	};
}[keyof T & string];

export type EdgeHandlers<C extends RpcContractShape, S, T extends EdgeTrustPolicies<S>> = {
	readonly [M in keyof C["methods"]]: EdgeHandler<C, M, S, T>;
};

export function edgeFamily<C extends RpcContractShape, S, T extends EdgeTrustPolicies<S>>(): <
	N extends keyof T & string,
	K extends keyof C["methods"] & string,
>(
	trust: N,
	methods: { readonly [M in K]: EdgeHandlerRun<C, M, S, T[N]> },
) => {
	readonly [M in K]: { readonly trust: N; readonly run: EdgeHandlerRun<C, M, S, T[N]> };
} {
	return (trust, methods) => {
		const stamped: Record<string, { trust: string; run: unknown }> = {};
		for (const [name, run] of Object.entries(methods)) {
			stamped[name] = { trust, run };
		}
		return stamped as never;
	};
}

export const EDGE_UNKNOWN_METHOD = "edge/unknown-method";
export const EDGE_UNTRUSTED_SENDER = "edge/untrusted-sender";
export const EDGE_HANDLER_FAILED = "edge/handler-failed";
export class EdgeCallFailure extends Error {
	readonly code: string;
	readonly detail: string;

	constructor(failure: { readonly code: string; readonly detail: string }) {
		super(`${failure.code}: ${failure.detail}`);
		this.name = "EdgeCallFailure";
		this.code = failure.code;
		this.detail = failure.detail;
	}
}

export class EdgeTrustPolicyMissingError extends Error {
	constructor(claim: { readonly edge: string; readonly method: string; readonly trust: string }) {
		super(
			`serveEdge(${claim.edge}): "${claim.method}" names undeclared trust policy "${claim.trust}".`,
		);
		this.name = "EdgeTrustPolicyMissingError";
	}
}

export interface EdgeDenial {
	readonly method: string;
	readonly trust: string;
}

export interface EdgeServerTransport<S> {
	handle(channel: string, run: (sender: S, payload: unknown) => Promise<unknown>): void;
	removeHandler(channel: string): void;
	broadcast(channel: string, payload: unknown): void;
}

export interface EdgeClientTransport {
	invoke(channel: string, payload: unknown): Promise<unknown>;
	on(channel: string, listener: (payload: unknown) => void): () => void;
}

export interface EdgeServer<C extends RpcContractShape> {
	emit<E extends keyof C["events"] & string>(event: E, payload: C["events"][E]): void;
	dispose(): void;
}

type EdgeReplyEnvelope =
	| { readonly ok: true; readonly value: unknown }
	| { readonly ok: false; readonly failure: { readonly code: string; readonly detail: string } };

function isEdgeReplyEnvelope(value: unknown): value is EdgeReplyEnvelope {
	if (typeof value !== "object" || value == null || !("ok" in value)) return false;
	return typeof (value as { ok: unknown }).ok === "boolean";
}

function methodChannel(edge: string, method: string): string {
	return `sand-rpc:${edge}:m:${method}`;
}

function eventChannel(edge: string, event: string): string {
	return `sand-rpc:${edge}:e:${event}`;
}

type ServableHandlers<S> = Record<
	string,
	{ readonly trust: string; readonly run: (args: unknown, sender: S) => unknown }
>;

export function serveEdge<C extends RpcContractShape, S, T extends EdgeTrustPolicies<S>>(
	contract: RpcContractTag<C>,
	table: EdgeMethodTable<C>,
	options: {
		readonly transport: EdgeServerTransport<S>;
		readonly trust: T;
		readonly handlers: EdgeHandlers<C, S, T>;
		readonly report?: (denial: EdgeDenial) => void;
	},
): EdgeServer<C> {
	const handlers = options.handlers as ServableHandlers<S>;
	const channels: string[] = [];

	for (const method of Object.keys(table)) {
		const handler = handlers[method];
		if (handler == null) {
			throw new EdgeTrustPolicyMissingError({
				edge: contract.edge,
				method,
				trust: "<missing handler>",
			});
		}
		const policy = options.trust[handler.trust];
		if (policy == null) {
			throw new EdgeTrustPolicyMissingError({ edge: contract.edge, method, trust: handler.trust });
		}
		const channel = methodChannel(contract.edge, method);
		channels.push(channel);
		options.transport.handle(channel, async (sender, payload): Promise<EdgeReplyEnvelope> => {
			if (policy.kind === "require" && !policy.test(sender)) {
				options.report?.({ method, trust: handler.trust });
				return {
					ok: false,
					failure: { code: EDGE_UNTRUSTED_SENDER, detail: policy.denial },
				};
			}
			try {
				return { ok: true, value: await handler.run(payload, sender) };
			} catch (error) {
				if (error instanceof EdgeCallFailure) {
					return { ok: false, failure: { code: error.code, detail: error.detail } };
				}
				const detail = error instanceof Error ? error.message : String(error);
				return { ok: false, failure: { code: EDGE_HANDLER_FAILED, detail } };
			}
		});
	}

	let disposed = false;
	return {
		emit: (event, payload) => {
			options.transport.broadcast(eventChannel(contract.edge, event), payload);
		},
		dispose: () => {
			if (disposed) return;
			disposed = true;
			for (const channel of channels) {
				options.transport.removeHandler(channel);
			}
		},
	};
}

export type EdgeBridgeMethod<C extends RpcContractShape, M extends keyof C["methods"]> =
	C["methods"][M]["args"] extends Record<string, never>
		? () => Promise<C["methods"][M]["reply"]>
		: (args: C["methods"][M]["args"]) => Promise<C["methods"][M]["reply"]>;

export type EdgeBridge<C extends RpcContractShape> = {
	readonly [M in keyof C["methods"]]: EdgeBridgeMethod<C, M>;
} & (RpcEventsDeclared<C> extends true
	? { subscribe(handlers: RpcEventHandlers<C>): () => void }
	: unknown);

export function bridgeEdge<C extends RpcContractShape>(
	contract: RpcContractTag<C>,
	table: EdgeMethodTable<C>,
	transport: EdgeClientTransport,
): EdgeBridge<C> {
	const bridge: Record<string, unknown> = {};

	const callMethod = async (method: string, payload: unknown): Promise<unknown> => {
		let reply: unknown;
		try {
			reply = await transport.invoke(methodChannel(contract.edge, method), payload);
		} catch (error) {
			const detail = error instanceof Error ? error.message : String(error);
			throw new EdgeCallFailure({ code: EDGE_UNKNOWN_METHOD, detail });
		}
		if (!isEdgeReplyEnvelope(reply)) {
			throw new EdgeCallFailure({
				code: EDGE_HANDLER_FAILED,
				detail: "The edge replied outside its envelope.",
			});
		}
		if (reply.ok) return reply.value;
		throw new EdgeCallFailure(reply.failure);
	};

	for (const [method, row] of Object.entries(table) as readonly [
		string,
		{ readonly args: "none" | "object" },
	][]) {
		bridge[method] =
			row.args === "none"
				? () => callMethod(method, {})
				: (args: unknown) => callMethod(method, args);
	}

	if (contract.hasEvents) {
		bridge.subscribe = (handlers: RpcEventHandlers<C>): (() => void) => {
			const unsubscribes: (() => void)[] = [];
			for (const [event, listener] of Object.entries(handlers)) {
				if (listener == null) continue;
				unsubscribes.push(
					transport.on(eventChannel(contract.edge, event), listener as (payload: unknown) => void),
				);
			}
			return () => {
				for (const unsubscribe of unsubscribes) unsubscribe();
			};
		};
	}

	return bridge as EdgeBridge<C>;
}
