/**
 * Which process owns a persisted value's truth.
 * - `host-durable`: Host-authoritative; Client replica reconciles on reconnect.
 * - `client-persisted`: laptop domain state (selected agent, drafts, journal).
 * - `desktop-preference`: native/window preferences via the desktop port.
 */
export type PersistenceScope = "host-durable" | "client-persisted" | "desktop-preference";

export const CLIENT_PERSISTENCE_CHANNELS = {
	read: "sand:client-persistence-read",
	write: "sand:client-persistence-write",
	remove: "sand:client-persistence-remove",
	listKeys: "sand:client-persistence-list-keys",
	migrate: "sand:client-persistence-migrate",
} as const;
